// Simple in-memory store standing in for a real database.
// Swap these functions for your DB calls (e.g. Prisma, Drizzle) in production.
const store = new Map<string, { notificationsEnabled: boolean }>()

export async function getNotificationPreference(userId: string): Promise<boolean> {
  return store.get(userId)?.notificationsEnabled ?? false
}

export async function setNotificationPreference(
  userId: string,
  enabled: boolean
): Promise<void> {
  store.set(userId, { notificationsEnabled: enabled })
}

