import { refresh } from 'next/cache'
import {
  getNotificationPreference,
  setNotificationPreference,
} from '@/lib/preferences'

// Replace with your real auth/session lookup.
async function getCurrentUserId(): Promise<string> {
  return 'demo-user'
}

export async function toggleNotifications() {
  const userId = await getCurrentUserId()
  const current = await getNotificationPreference(userId)
  await setNotificationPreference(userId, !current)

  // Refresh the client router so the current page re-renders with the
  // updated preference, without navigating away.
  refresh()
}

