import { toggleNotifications } from './actions'
import { getNotificationPreference } from '@/lib/preferences'

export default async function Home() {
  const enabled = await getNotificationPreference('demo-user')

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are <strong>{enabled ? 'On' : 'Off'}</strong>
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          {enabled ? 'Turn notifications off' : 'Turn notifications on'}
        </button>
      </form>
    </main>
  )
}

